using System.Linq;using System.Text;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.SceneManagement;
namespace XuanwuTools { public static class SceneAuditor {
 [MenuItem(Common.Menu+"01 Scene audit")] public static void Audit()=>Common.Run(()=>{var s=new StringBuilder();s.AppendLine("scene="+SceneManager.GetActiveScene().path+" unity="+Application.unityVersion+" pipeline="+(GraphicsSettings.currentRenderPipeline?GraphicsSettings.currentRenderPipeline.name:"Built-in"));foreach(var t in Common.SceneObjects<Terrain>())if(t.terrainData)s.AppendLine($"Terrain {Common.PathOf(t)} position={t.transform.position} size={t.terrainData.size} heightmap={t.terrainData.heightmapResolution} data={AssetDatabase.GetAssetPath(t.terrainData)}");foreach(var c in Common.SceneObjects<CharacterController>())s.AppendLine($"Controller {Common.PathOf(c)} radius={c.radius} height={c.height} slope={c.slopeLimit} step={c.stepOffset} center={c.center}");foreach(var c in Common.SceneObjects<Camera>())s.AppendLine($"Camera {Common.PathOf(c)} fov={c.fieldOfView} near={c.nearClipPlane} far={c.farClipPlane}");s.AppendLine("roots="+string.Join(", ",SceneManager.GetActiveScene().GetRootGameObjects().Select(x=>x.name)));s.AppendLine("Roll distance, camera rig and gameplay anchors require manual inspection.");Common.Report("scene-audit",s.ToString());});}}
